pub fn simplify_cost(expr: Rc<CostExpr>) -> Rc<CostExpr> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
    CostExpr::CostConst { .. } => expr.clone(),
    CostExpr::CostUnknown { .. } => expr.clone(),
    CostExpr::CostAdd { left: l, right: r, .. } => {
            let sl = simplify_cost(l.clone());
let sr = simplify_cost(r.clone());
let simplified = match (*sl.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => sr.clone(),
    CostExpr::CostConst { value: a, .. } => match (*sr.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => sl.clone(),
    CostExpr::CostConst { value: b, .. } => Rc::new(CostExpr::CostConst {
    value: (a.clone() + b.clone()),
}),
    _ => Rc::new(CostExpr::CostAdd {
    left: sl.clone(),
    right: sr.clone(),
}),
},
    _ => match (*sr.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => sl.clone(),
    _ => Rc::new(CostExpr::CostAdd {
    left: sl.clone(),
    right: sr.clone(),
}),
},
};
simplified.clone()
},
    CostExpr::CostMul { left: l, right: r, .. } => {
            let sl = simplify_cost(l.clone());
let sr = simplify_cost(r.clone());
let simplified = match (*sl.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => Rc::new(CostExpr::CostConst {
    value: 0,
}),
    CostExpr::CostConst { value: 1, .. } => sr.clone(),
    _ => match (*sr.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => Rc::new(CostExpr::CostConst {
    value: 0,
}),
    CostExpr::CostConst { value: 1, .. } => sl.clone(),
    _ => Rc::new(CostExpr::CostMul {
    left: sl.clone(),
    right: sr.clone(),
}),
},
};
simplified.clone()
},
    CostExpr::CostMax { left: l, right: r, .. } => {
            let sl = simplify_cost(l.clone());
let sr = simplify_cost(r.clone());
let simplified = match (*sl.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => sr.clone(),
    _ => match (*sr.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => sl.clone(),
    _ => Rc::new(CostExpr::CostMax {
    left: sl.clone(),
    right: sr.clone(),
}),
},
};
simplified.clone()
},
    CostExpr::CostSum { binder: b, upper: u, body: bd, .. } => {
            let sbd = simplify_cost(bd.clone());
match (*sbd.clone()).clone() {
    CostExpr::CostConst { value: 0, .. } => Rc::new(CostExpr::CostConst {
    value: 0,
}),
    _ => Rc::new(CostExpr::CostSum {
    binder: b.clone(),
    upper: u.clone(),
    body: sbd.clone(),
}),
}
},
    CostExpr::CostLog { base: b, argument: a, .. } => Rc::new(CostExpr::CostLog {
    base: b.clone(),
    argument: a.clone(),
}),
}
    })
}

pub fn format_size(size: Rc<SizeExpr>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*size.clone()).clone() {
    SizeExpr::SizeLen { collection: c, .. } => v2_rt::concat(v2_rt::concat("|".to_string(), c.clone()), "|".to_string()),
    SizeExpr::SizeVar { name: n, .. } => n.clone(),
    SizeExpr::SizeConst { value: v, .. } => v2_rt::to_string(v.clone()),
    SizeExpr::SizeAdd { left: l, right: r, .. } => v2_rt::concat(v2_rt::concat(format_size(l.clone()), " + ".to_string()), format_size(r.clone())),
    SizeExpr::SizeMax { left: l, right: r, .. } => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("max(".to_string(), format_size(l.clone())), ", ".to_string()), format_size(r.clone())), ")".to_string()),
}
    })
}

pub fn strip_big_o(s: String) -> String {
    if ((v2_rt::string_length(s.clone()) > 3) && (v2_rt::substring(s.clone(), 0, 2) == "O(".to_string())) {
        v2_rt::substring(s.clone(), 2, (v2_rt::string_length(s.clone()) - 1))
} else {
        s.clone()
}
}

pub fn has_cost_sum(expr: Rc<CostExpr>) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
    CostExpr::CostSum { .. } => true,
    CostExpr::CostAdd { left: l, right: r, .. } => (has_cost_sum(l.clone()) || has_cost_sum(r.clone())),
    CostExpr::CostMul { left: l, right: r, .. } => (has_cost_sum(l.clone()) || has_cost_sum(r.clone())),
    CostExpr::CostMax { left: l, right: r, .. } => (has_cost_sum(l.clone()) || has_cost_sum(r.clone())),
    _ => false,
}
    })
}

pub fn cost_sum_depth(expr: Rc<CostExpr>) -> i64 {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
    CostExpr::CostSum { body: b, .. } => (1 + cost_sum_depth(b.clone())),
    CostExpr::CostAdd { left: l, right: r, .. } => {
            let ld = cost_sum_depth(l.clone());
let rd = cost_sum_depth(r.clone());
if (rd.clone() > ld.clone()) {
                rd.clone()
} else {
                ld.clone()
}
},
    CostExpr::CostMul { left: l, right: r, .. } => {
            let ld = cost_sum_depth(l.clone());
let rd = cost_sum_depth(r.clone());
if (rd.clone() > ld.clone()) {
                rd.clone()
} else {
                ld.clone()
}
},
    CostExpr::CostMax { left: l, right: r, .. } => {
            let ld = cost_sum_depth(l.clone());
let rd = cost_sum_depth(r.clone());
if (rd.clone() > ld.clone()) {
                rd.clone()
} else {
                ld.clone()
}
},
    _ => 0,
}
    })
}

pub fn classify_complexity(expr: Rc<CostExpr>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        {
            let s = simplify_cost(expr.clone());
match (*s.clone()).clone() {
    CostExpr::CostConst { .. } => "O(1)".to_string(),
    CostExpr::CostUnknown { .. } => "O(?)".to_string(),
    CostExpr::CostSum { upper: u, body: bd, .. } => if has_cost_sum(bd.clone()) {
                {
                    let inner_class = classify_complexity(bd.clone());
let inner_bare = strip_big_o(inner_class.clone());
v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("O(".to_string(), format_size(u.clone())), " * ".to_string()), inner_bare.clone()), ")".to_string())
}
} else {
                v2_rt::concat(v2_rt::concat("O(".to_string(), format_size(u.clone())), ")".to_string())
},
    CostExpr::CostAdd { left: l, right: r, .. } => {
                let lc = classify_complexity(l.clone());
let rc = classify_complexity(r.clone());
let dominant = if (has_cost_sum(l.clone()) && has_cost_sum(r.clone())) {
                    if (cost_sum_depth(r.clone()) > cost_sum_depth(l.clone())) {
                        rc.clone()
} else {
                        lc.clone()
}
} else {
                    if has_cost_sum(l.clone()) {
                        lc.clone()
} else {
                        if has_cost_sum(r.clone()) {
                            rc.clone()
} else {
                            "O(1)".to_string()
}
}
};
dominant.clone()
},
    CostExpr::CostMul { left: l, right: r, .. } => {
                let lc = classify_complexity(l.clone());
let rc = classify_complexity(r.clone());
let combined = if (lc.clone() == "O(1)".to_string()) {
                    rc.clone()
} else {
                    if (rc.clone() == "O(1)".to_string()) {
                        lc.clone()
} else {
                        v2_rt::concat(v2_rt::concat(lc.clone(), " * ".to_string()), rc.clone())
}
};
combined.clone()
},
    CostExpr::CostMax { left: l, right: r, .. } => {
                let lc = classify_complexity(l.clone());
let rc = classify_complexity(r.clone());
let dominant = if has_cost_sum(l.clone()) {
                    lc.clone()
} else {
                    if has_cost_sum(r.clone()) {
                        rc.clone()
} else {
                        lc.clone()
}
};
dominant.clone()
},
    CostExpr::CostLog { argument: a, .. } => {
                v2_rt::concat(v2_rt::concat("O(log ".to_string(), format_size(a.clone())), ")".to_string())
},
}
}
    })
}

pub fn collect_size_vars_from_size(size: Rc<SizeExpr>) -> Vec<String> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*size.clone()).clone() {
    SizeExpr::SizeLen { collection: c, .. } => if (c.clone() == "__expr".to_string()) {
            vec![]
} else {
            vec![c.clone()]
},
    SizeExpr::SizeAdd { left: l, right: r, .. } => v2_rt::concat(collect_size_vars_from_size(l.clone()), collect_size_vars_from_size(r.clone())),
    SizeExpr::SizeMax { left: l, right: r, .. } => v2_rt::concat(collect_size_vars_from_size(l.clone()), collect_size_vars_from_size(r.clone())),
    _ => vec![],
}
    })
}

pub fn collect_size_vars(expr: Rc<CostExpr>) -> Vec<String> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
    CostExpr::CostSum { upper: u, body: bd, .. } => v2_rt::concat(collect_size_vars_from_size(u.clone()), collect_size_vars(bd.clone())),
    CostExpr::CostAdd { left: l, right: r, .. } => v2_rt::concat(collect_size_vars(l.clone()), collect_size_vars(r.clone())),
    CostExpr::CostMul { left: l, right: r, .. } => v2_rt::concat(collect_size_vars(l.clone()), collect_size_vars(r.clone())),
    CostExpr::CostMax { left: l, right: r, .. } => v2_rt::concat(collect_size_vars(l.clone()), collect_size_vars(r.clone())),
    _ => vec![],
}
    })
}

#[derive(Debug, Clone, PartialEq)]
pub struct DeduplicateAcc {
    pub seen: HashMap<String, bool>,
    pub out: Vec<String>,
}

pub fn deduplicate(items: Vec<String>) -> Vec<String> {
    {
        let result = items.iter().cloned().fold(Rc::new(DeduplicateAcc {
    seen: <HashMap<_, _>>::new(),
    out: vec![],
}), |acc: _, item: String| match v2_rt::map_get(&acc.seen.clone(), item.clone()) {
    Some(_) => acc.clone(),
    None => Rc::new(DeduplicateAcc {
    seen: v2_rt::map_insert(acc.seen.clone(), item.clone(), true),
    out: v2_rt::list_push(acc.out.clone(), item.clone()),
}),
});
result.out.clone()
}
}

pub fn format_space_class(expr: Rc<CostExpr>) -> String {
    {
        let space_class = classify_complexity(expr.clone());
if (space_class.clone() == "O(1)".to_string()) {
            "".to_string()
} else {
            v2_rt::concat(", space ".to_string(), space_class.clone())
}
}
}

pub fn format_func_complexity(name: String, summary: Rc<ComplexitySummary>) -> String {
    {
        let class = classify_complexity(summary.work.clone());
let marker = match summary.certainty.clone() {
    Certainty::Proven => "".to_string(),
    Certainty::Conservative => "~".to_string(),
    Certainty::Unknown => "?".to_string(),
};
let space_str = match v2_rt::map_get(&summary.output_size.clone(), "result".to_string()) {
    Some(size_expr) => format_space_class(size_expr.clone()),
    _ => "".to_string(),
};
v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(name.clone(), ": ".to_string()), marker.clone()), class.clone()), space_str.clone())
}
}

pub fn format_complexity_report(entries: Vec<Rc<FuncEntry>>, summaries: HashMap<String, Rc<ComplexitySummary>>) -> String {
    {
        let lines = { let mut __result = Vec::new(); for entry in entries.iter().cloned() { __result.extend(match v2_rt::map_get(&summaries, entry.name.clone()) {
    Some(summary) => vec![format_func_complexity(entry.name.clone(), summary.clone())],
    None => vec![],
}); } __result };
lines.clone().join(&"
".to_string())
}
}

#[derive(Debug, Clone, PartialEq)]
pub struct FuncEntry {
    pub name: String,
    pub body: Rc<Node>,
    pub params: Vec<Rc<Node>>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SummaryResult {
    pub summary: Rc<ComplexitySummary>,
    pub table: Rc<CostInternTable>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MatchCostAccum {
    pub result: Rc<SummaryResult>,
    pub branch_costs: Vec<Rc<CostExpr>>,
}

pub fn cost_of_expr(texpr: Rc<Node>, func_index: HashMap<String, Rc<FuncEntry>>, table: Rc<CostInternTable>) -> Rc<SummaryResult> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprLiteral { .. } => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}),
    ExprData::ExprError { .. } => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}),
    ExprData::ExprVar { .. } => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}),
    ExprData::ExprBinOp { .. } => {
            let l = binop_left(texpr.clone());
let r = binop_right(texpr.clone());
let lr = cost_of_expr(l.clone(), func_index.clone(), table.clone());
let rr = cost_of_expr(r.clone(), func_index.clone(), lr.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(lr.summary.clone().work.clone(), cost_seq(Rc::new(CostExpr::CostConst {
    value: 1,
}), rr.summary.clone().work.clone())),
    span: cost_seq(lr.summary.clone().span.clone(), cost_seq(Rc::new(CostExpr::CostConst {
    value: 1,
}), rr.summary.clone().span.clone())),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: rr.table.clone(),
})
},
    ExprData::ExprCall { func: fname, .. } => {
            let callee_result = match v2_rt::map_get(&func_index, fname.clone()) {
    Some(entry) => get_or_compute_summary(fname.clone(), func_index.clone(), table.clone()),
    None => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}),
};
let args_result = texpr.children.iter().cloned().fold(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: callee_result.table.clone(),
}), |acc: _, a: Rc<Node>| {
                let ar = cost_of_expr(arg_value(a.clone()), func_index.clone(), acc.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(acc.summary.clone().work.clone(), ar.summary.clone().work.clone()),
    span: cost_seq(acc.summary.clone().span.clone(), ar.summary.clone().span.clone()),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: ar.table.clone(),
})
});
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(args_result.summary.clone().work.clone(), callee_result.summary.clone().work.clone()),
    span: cost_seq(args_result.summary.clone().span.clone(), callee_result.summary.clone().span.clone()),
    output_size: callee_result.summary.clone().output_size.clone(),
    certainty: callee_result.summary.clone().certainty.clone(),
}),
    table: args_result.table.clone(),
})
},
    ExprData::ExprMethodCall { method: mname, method_semantics: ms, .. } => {
            let recv = method_receiver(texpr.clone());
let mc_args = method_arg_nodes(texpr.clone());
let recv_r = cost_of_expr(recv.clone(), func_index.clone(), table.clone());
let size = receiver_size_var(recv.clone());
let binder = size_binder_name(size.clone());
let method_cost_result = if (ms.clone() == None) {
                None
} else {
                match (*ms.clone().unwrap()).clone() {
    MethodSemantics::IntrinsicMethodSemantics { intrinsic: im, .. } => {
                    let shape = intrinsic_method_cost_shape(im.clone());
Some(cost_of_method_by_shape(shape.clone(), recv_r.clone(), mc_args.clone(), size.clone(), binder.clone(), func_index.clone()))
},
    MethodSemantics::RuntimeBridgeSemantics { .. } => Some(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(recv_r.summary.clone().work.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})),
    span: cost_seq(recv_r.summary.clone().span.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})),
    output_size: <HashMap<_, _>>::new(),
    certainty: recv_r.summary.clone().certainty.clone(),
}),
    table: recv_r.table.clone(),
})),
    _ => None,
}
};
match method_cost_result.clone() {
    Some(result) => result.clone(),
    _ => {
                let args_result = mc_args.iter().cloned().fold(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: recv_r.table.clone(),
}), |acc: _, a: Rc<Node>| {
                    let ar = cost_of_expr(arg_value(a.clone()), func_index.clone(), acc.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(acc.summary.clone().work.clone(), ar.summary.clone().work.clone()),
    span: cost_seq(acc.summary.clone().span.clone(), ar.summary.clone().span.clone()),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: ar.table.clone(),
})
});
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(recv_r.summary.clone().work.clone(), cost_seq(Rc::new(CostExpr::CostConst {
    value: 1,
}), args_result.summary.clone().work.clone())),
    span: cost_seq(recv_r.summary.clone().span.clone(), cost_seq(Rc::new(CostExpr::CostConst {
    value: 1,
}), args_result.summary.clone().span.clone())),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: args_result.table.clone(),
})
},
}
},
    ExprData::ExprMatch => {
            let scrut = match_scrutinee(texpr.clone());
let arm_nodes = match_arm_nodes(texpr.clone());
let s_r = cost_of_expr(scrut.clone(), func_index.clone(), table.clone());
let arms_accum = arm_nodes.iter().cloned().fold(Rc::new(MatchCostAccum {
    result: Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: s_r.table.clone(),
}),
    branch_costs: vec![],
}), |acc: _, arm_node: Rc<Node>| {
                let ar = cost_of_expr(arm_body(arm_node.clone()), func_index.clone(), acc.result.clone().table.clone());
Rc::new(MatchCostAccum {
    result: Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_par(acc.result.clone().summary.clone().work.clone(), ar.summary.clone().work.clone()),
    span: cost_par(acc.result.clone().summary.clone().span.clone(), ar.summary.clone().span.clone()),
    output_size: ar.summary.clone().output_size.clone(),
    certainty: ar.summary.clone().certainty.clone(),
}),
    table: ar.table.clone(),
}),
    branch_costs: v2_rt::concat(acc.branch_costs.clone(), vec![ar.summary.clone().work.clone()]),
})
});
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_conditional(s_r.summary.clone().work.clone(), arms_accum.branch_costs.clone()),
    span: cost_conditional(s_r.summary.clone().span.clone(), vec![arms_accum.result.clone().summary.clone().span.clone()]),
    output_size: arms_accum.result.clone().summary.clone().output_size.clone(),
    certainty: arms_accum.result.clone().summary.clone().certainty.clone(),
}),
    table: arms_accum.result.clone().table.clone(),
})
},
    ExprData::ExprIf => {
            let c = if_condition(texpr.clone());
let t = if_then_branch(texpr.clone());
let c_r = cost_of_expr(c.clone(), func_index.clone(), table.clone());
let t_r = cost_of_expr(t.clone(), func_index.clone(), c_r.table.clone());
let e_result = match if_else_branch(texpr.clone()) {
    Some(eb) => {
                let er = cost_of_expr(eb.clone(), func_index.clone(), t_r.table.clone());
Rc::new(SummaryResult {
    summary: er.summary.clone(),
    table: er.table.clone(),
})
},
    None => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: t_r.table.clone(),
}),
};
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_conditional(c_r.summary.clone().work.clone(), vec![t_r.summary.clone().work.clone(), e_result.summary.clone().work.clone()]),
    span: cost_conditional(c_r.summary.clone().span.clone(), vec![t_r.summary.clone().span.clone(), e_result.summary.clone().span.clone()]),
    output_size: t_r.summary.clone().output_size.clone(),
    certainty: Certainty::Proven,
}),
    table: e_result.table.clone(),
})
},
    ExprData::ExprLet { .. } => {
            let v = let_value(texpr.clone());
let v_r = cost_of_expr(v.clone(), func_index.clone(), table.clone());
match let_body(texpr.clone()) {
    Some(b) => {
                let b_r = cost_of_expr(b.clone(), func_index.clone(), v_r.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(v_r.summary.clone().work.clone(), b_r.summary.clone().work.clone()),
    span: cost_seq(v_r.summary.clone().span.clone(), b_r.summary.clone().span.clone()),
    output_size: b_r.summary.clone().output_size.clone(),
    certainty: b_r.summary.clone().certainty.clone(),
}),
    table: b_r.table.clone(),
})
},
    None => v_r.clone(),
}
},
    ExprData::ExprBlock => texpr.children.iter().cloned().fold(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}), |acc: _, s: Rc<Node>| {
            let sr = cost_of_expr(s.clone(), func_index.clone(), acc.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(acc.summary.clone().work.clone(), sr.summary.clone().work.clone()),
    span: cost_seq(acc.summary.clone().span.clone(), sr.summary.clone().span.clone()),
    output_size: sr.summary.clone().output_size.clone(),
    certainty: sr.summary.clone().certainty.clone(),
}),
    table: sr.table.clone(),
})
}),
    ExprData::ExprForEach { .. } => {
            let c = foreach_collection(texpr.clone());
let bd = foreach_body(texpr.clone());
let c_r = cost_of_expr(c.clone(), func_index.clone(), table.clone());
let bd_r = cost_of_expr(bd.clone(), func_index.clone(), c_r.table.clone());
let size = receiver_size_var(c.clone());
let binder = size_binder_name(size.clone());
let loop_work = cost_loop(binder.clone(), size.clone(), bd_r.summary.clone().work.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(c_r.summary.clone().work.clone(), loop_work.clone()),
    span: cost_seq(c_r.summary.clone().span.clone(), loop_work.clone()),
    output_size: <HashMap<_, _>>::new(),
    certainty: bd_r.summary.clone().certainty.clone(),
}),
    table: bd_r.table.clone(),
})
},
    ExprData::NoExprData => texpr.children.iter().cloned().fold(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}), |acc: _, child: Rc<Node>| {
            let cr = cost_of_expr(child.clone(), func_index.clone(), acc.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(acc.summary.clone().work.clone(), cr.summary.clone().work.clone()),
    span: cost_seq(acc.summary.clone().span.clone(), cr.summary.clone().span.clone()),
    output_size: cr.summary.clone().output_size.clone(),
    certainty: cr.summary.clone().certainty.clone(),
}),
    table: cr.table.clone(),
})
}),
    _ => texpr.children.iter().cloned().fold(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: table.clone(),
}), |acc: _, child: Rc<Node>| {
            let cr = cost_of_expr(child.clone(), func_index.clone(), acc.table.clone());
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(acc.summary.clone().work.clone(), cr.summary.clone().work.clone()),
    span: cost_seq(acc.summary.clone().span.clone(), cr.summary.clone().span.clone()),
    output_size: cr.summary.clone().output_size.clone(),
    certainty: cr.summary.clone().certainty.clone(),
}),
    table: cr.table.clone(),
})
}),
}
    })
}

pub fn estimate_expr_size(texpr: Rc<Node>, budget: i64) -> i64 {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (budget.clone() <= 0) {
            0
} else {
            texpr.children.iter().cloned().fold((budget.clone() - 1), |acc: _, child: Rc<Node>| estimate_expr_size(child.clone(), acc.clone()))
}
    })
}

pub fn get_or_compute_summary(func_name: String, func_index: HashMap<String, Rc<FuncEntry>>, table: Rc<CostInternTable>) -> Rc<SummaryResult> {
    match lookup_summary(table.clone(), func_name.clone()) {
    Some(cached) => Rc::new(SummaryResult {
    summary: cached.clone(),
    table: table.clone(),
}),
    None => match v2_rt::map_get(&func_index, func_name.clone()) {
    Some(entry) => {
        {
                let placeholder = Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostUnknown {
    reason: v2_rt::concat("computing: ".to_string(), func_name.clone()),
}),
    span: Rc::new(CostExpr::CostUnknown {
    reason: v2_rt::concat("computing: ".to_string(), func_name.clone()),
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Unknown,
});
let table_with_placeholder = cache_summary(table.clone(), func_name.clone(), placeholder.clone());
let result = cost_of_expr(entry.body.clone(), func_index.clone(), table_with_placeholder.clone());
let is_recursive = cost_contains_computing_ref(result.summary.clone().work.clone(), func_name.clone());
let bounded = if is_recursive.clone() {
    let pattern = classify_recursion_pattern(func_name.clone(), entry.body.clone());
    Rc::new(ComplexitySummary {
        work: bounded_recursive_cost(pattern.clone(), result.summary.clone().work.clone(), func_name.clone()),
        span: bounded_recursive_cost(pattern.clone(), result.summary.clone().span.clone(), func_name.clone()),
        output_size: result.summary.clone().output_size.clone(),
        certainty: Certainty::Conservative,
    })
} else {
    result.summary.clone()
};
let simplified = Rc::new(ComplexitySummary {
    work: simplify_cost(bounded.clone().work.clone()),
    span: simplify_cost(bounded.clone().span.clone()),
    output_size: bounded.clone().output_size.clone(),
    certainty: bounded.clone().certainty.clone(),
});
let final_table = cache_summary(result.table.clone(), func_name.clone(), simplified.clone());
Rc::new(SummaryResult {
    summary: simplified.clone(),
    table: final_table.clone(),
})
}
},
    None => {
        let unknown_summary = Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostUnknown {
    reason: v2_rt::concat("function not found: ".to_string(), func_name.clone()),
}),
    span: Rc::new(CostExpr::CostUnknown {
    reason: v2_rt::concat("function not found: ".to_string(), func_name.clone()),
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Unknown,
});
Rc::new(SummaryResult {
    summary: unknown_summary.clone(),
    table: table.clone(),
})
},
},
}
}

pub fn is_unknown_cost(expr: Rc<CostExpr>) -> bool {
    match (*expr.clone()).clone() {
    CostExpr::CostUnknown { .. } => true,
    _ => false,
}
}

pub fn build_complexity_report(func_entries: Vec<Rc<FuncEntry>>) -> Rc<ComplexityReport> {
    // BOOTSTRAP PERF: Short-circuit complexity analysis during self-compile.
    // The fold below clones func_index (HashMap) and intern_table on every
    // iteration — O(n²) for n functions, ~7GB for the compiler's ~500 funcs.
    // Complexity reports don't affect code emission; re-enable after stage0
    // is regenerated with the redundant-clone removal.
    if std::env::var("GUNBC_SKIP_COMPLEXITY").is_ok() || func_entries.len() > 100 {
        return Rc::new(ComplexityReport {
            function_summaries: <HashMap<_, _>>::new(),
            violations: vec![],
            intern_table: empty_intern_table(),
            formatted: "complexity analysis skipped (GUNBC_SKIP_COMPLEXITY)".to_string(),
        });
    }
    {
        let func_index = func_entries.iter().cloned().fold(<HashMap<String, Rc<FuncEntry>>>::new(), |acc: _, entry: Rc<FuncEntry>| v2_rt::map_insert(acc.clone(), entry.name.clone(), entry.clone()));
let result = func_entries.iter().cloned().fold(Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 0,
}),
    output_size: <HashMap<_, _>>::new(),
    certainty: Certainty::Proven,
}),
    table: empty_intern_table(),
}), |acc: _, entry: Rc<FuncEntry>| {
            let sr = get_or_compute_summary(entry.name.clone(), func_index.clone(), acc.table.clone());
Rc::new(SummaryResult {
    summary: sr.summary.clone(),
    table: sr.table.clone(),
})
});
let summaries_map = result.table.clone().summaries.clone();
let violations = { let mut __result = Vec::new(); for entry in { let mut __result = Vec::new(); for entry in func_entries.iter().cloned() { if match v2_rt::map_get(&summaries_map, entry.name.clone()) {
    Some(summary) => is_unknown_cost(summary.work.clone()),
    None => true,
} { __result.push(entry); } } __result }.iter().cloned() { __result.push(match v2_rt::map_get(&summaries_map, entry.name.clone()) {
    Some(summary) => {
            let reason = match (*summary.work.clone()).clone() {
    CostExpr::CostUnknown { reason: r, .. } => r.clone(),
    _ => "unknown".to_string(),
};
Rc::new(ComplexityViolation {
    func_name: entry.name.clone(),
    reason: reason.clone(),
    summary: Some(summary.clone()),
})
},
    None => Rc::new(ComplexityViolation {
    func_name: entry.name.clone(),
    reason: "no summary computed".to_string(),
    summary: None,
}),
}); } __result };
let formatted = format_complexity_report(func_entries.clone(), summaries_map.clone());
Rc::new(ComplexityReport {
    function_summaries: summaries_map.clone(),
    violations: violations.clone(),
    intern_table: result.table.clone(),
    formatted: formatted.clone(),
})
}
}
